  if(q.has('etapa')){if(q.getAll('etapa').length!==1||!/^\d{1,2}$/.test(q.get('etapa')))return null;
    p=p.etapasComerciales?.find(t=>Number(t.etapa??t.detalleUrl?.split('#etapa-')[1])===Number(q.get('etapa')));if(!p)return null;}
